(445, 'documents', 'created', 'App\\Models\\Document', '01ksah4j3f4vymmcx5g6fa67wd', 'created', 'App\\Models\\User', '01kr33ez5sjjtbq1jwq8dnkxcz', '{\"attributes\":{\"user_id\":\"01kr33ez5sjjtbq1jwq8dnkxcz\",\"period_id\":\"01krp69j6be8g4sg8j00ec6r0e\",\"type\":\"weekly_report\",\"title\":\"Weekly Report - Week 21\",\"state\":\"submitted\",\"month\":null,\"year\":null,\"main_target\":null,\"target_accomplished\":0,\"target_explanation\":\"The planned visit to the Regional Education Office in Arusha was not conducted due to the absence of official authorization from TAMISEMI and introduction\\/identification documents required for formal engagement with government authorities. Follow-up arrangements will be made once the necessary documents are available.\",\"file_path\":null,\"original_filename\":null}}', NULL, '2026-05-23 16:42:02', '2026-05-23 16:42:02'),
(446, 'documents', 'created', 'App\\Models\\Document', '01ksak2sfw510mqxx3dvrp1wxh', 'created', 'App\\Models\\User', '01kr33ez5sjjtbq1jwq8dnkxcz', '{\"attributes\":{\"user_id\":\"01kr33ez5sjjtbq1jwq8dnkxcz\",\"period_id\":\"01ks813k2j8sbpzyqnj5ty4sz4\",\"type\":\"weekly_plan\",\"title\":\"Weekly Plan - Week 22\",\"state\":\"submitted\",\"month\":null,\"year\":null,\"main_target\":\"Participate in the Rwanda (Kigali) STEM boot camp and the Uganda learning visit in order to strengthen practical STEM and innovation skills through hands-on training, collaborative problem-solving, and exposure visits, while building regional networks, enhancing teamwork and presentation abilities, and gaining cross-border learning experiences that can be applied to local education and innovation initiatives.\",\"target_accomplished\":null,\"target_explanation\":null,\"file_path\":null,\"original_filename\":null}}', NULL, '2026-05-23 17:16:01', '2026-05-23 17:16:01'),
