(449, 'documents', 'created', 'App\\Models\\Document', '01ksawda1040y0q0bywgf67gnq', 'created', 'App\\Models\\User', '01kr33h60mb6v75fp095eexkd8', '{\"attributes\":{\"user_id\":\"01kr33h60mb6v75fp095eexkd8\",\"period_id\":\"01ks813k2j8sbpzyqnj5ty4sz4\",\"type\":\"weekly_plan\",\"title\":\"Weekly Plan - Week 22\",\"state\":\"submitted\",\"month\":null,\"year\":null,\"main_target\":\"To participate in the STEM and TVET Pedagogical Innovation Bootcamp in Rwanda to enhance pedagogical skills, share best practices, and strengthen capacity in innovative teaching approaches for improved STEM and TVET education delivery across AU member states, while ensuring effective reporting and continuation of CHOMOZA STEM project.\",\"target_accomplished\":null,\"target_explanation\":null,\"file_path\":null,\"original_filename\":null}}', NULL, '2026-05-23 19:59:03', '2026-05-23 19:59:03'),
